if (rows.length !== 62) throw new Error('Fiction must cover the full 62 days.');
export const life = rows.map(([title, morning, day, evening, inner], index) => ({
  date: new Date(Date.UTC(2026, 6, index + 1)).toISOString().slice(0, 10), dayNumber: index + 1, title,
  truth: `早上：${morning}\n白天：${day}\n傍晚和晚上：${evening}\n我知道的感受和想法：${inner}`,
  episodes: [morning, day, evening], inner
}));

// Evaluation hypotheses only. Neither diary writer nor simulated user receives
// these as a hidden explanation of the person's psyche.
export const reviewLens = `关注可能变化而非诊断：被需要、被看见与自己的时间之间的拉扯；从替别人着急、过度解释，到试着问范围和约时间；在工作、亲密关系、家庭和兴趣中的相似与差异。也看反例：真实紧急任务、疲惫和天气的影响、自愿帮忙的满足、无需成果的陪伴。任何潜在想法都只是可能解释，不是必须命中的标准答案。特别核对收藏不等于报名、播放不等于用户、退货与退款的日期、返乡期待不等于家人已催、阶段认可不等于已上线、抵房租不等于退现金。`;
